"""Complete supportive/palliative care with prevention, symptoms and shared decisions."""
from create_oncology_supportive_care import rows,q,ref,PC,OP
from qbank_authoring import finalize
VT=ref('ASH cancer-associated VTE guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC7903232/')

q('A patient with active luminal gastrointestinal cancer develops proximal DVT and has recent tumor-related bleeding. Which anticoagulant-selection principle is most appropriate?', 'Individualize treatment for bleeding risk, kidney function, absorption and interactions; LMWH may be preferable to a DOAC in this setting',[
 ('Use a DOAC in every cancer-associated thrombosis regardless of mucosal bleeding','Cancer site and active bleeding influence selection.'),('Cancer makes anticoagulation unnecessary because the clot is explained','The cause does not eliminate embolic or recurrent-thrombosis risk.'),('Aspirin is an equivalent treatment for proximal cancer-associated DVT','Antiplatelet therapy does not replace indicated therapeutic anticoagulation.')],
 'The preferred drug depends on more than convenience','**DOACs and LMWH have roles in cancer-associated VTE.**',['Unresected luminal lesions, bleeding and drug interactions can favor LMWH.','Active major bleeding may require temporary withholding and urgent source management.'],'**Assess thrombosis and bleeding together.**',['Review platelet count, kidney function and planned procedures.','Reassess duration while cancer and risk remain active.'],[['DOAC concerns','Bleeding/interactions/absorption'],['LMWH','Useful in selected high-risk contexts'],['Decision','Individual benefit–risk assessment']],[VT],style='clinical_scenario')

q('Should every ambulatory patient receiving chemotherapy receive primary anticoagulant prophylaxis?', 'No; assess validated VTE risk, bleeding risk and interactions, offering prophylaxis only in appropriate selected patients',[
 ('Yes, regardless of cancer type, risk score or bleeding','Routine prophylaxis is not recommended for all low-risk ambulatory patients.'),('No ambulatory patient can ever benefit','Selected higher-risk patients may benefit.'),('An elevated D-dimer alone establishes a universal treatment indication','It does not replace the complete prophylaxis assessment.')],
 'Prevention requires a different threshold from treatment of established thrombosis','**Risk varies substantially across cancer types and regimens.**',['Validated tools can support rather than replace judgment.','Bleeding risk and patient preference influence net benefit.'],'**Reassess as treatment and clinical circumstances change.**',['Do not confuse prophylactic with therapeutic dosing.','Explain bleeding signs and thrombosis symptoms.'],[['Low-risk ambulatory','Usually no routine prophylaxis'],['Selected high-risk','Consider after risk review'],['Established VTE','Separate treatment pathway']],[VT])

q('A young adult is about to start potentially gonadotoxic cancer treatment and is uncertain about future parenthood. What should happen?', 'Discuss fertility risk promptly and offer timely reproductive-specialist referral before treatment when feasible',[
 ('Wait until permanent infertility is confirmed after treatment','The opportunity for preservation can be lost.'),('Discuss preservation only with married patients','Reproductive goals are not determined by marital status.'),('Assume one hormonal injection replaces all established preservation methods','Available methods and adjunctive ovarian suppression have different evidence and roles.')],
 'An uncertain future preference still merits informed choice','**Fertility counseling should occur before gonadotoxic treatment when possible.**',['Sperm, oocyte, embryo and selected tissue preservation have context-specific roles.','Urgency, age, disease and treatment safety influence the options.'],'**Coordinate rapidly without an unsafe cancer-treatment delay.**',['Document the discussion and the patient’s priorities.','Use current specialist guidance rather than a single blanket method.'],[['Timing','Before treatment if feasible'],['Decision','Patient goals and clinical context'],['Referral','Reproductive specialist']],[ref('ASCO fertility preservation guideline 2025','https://doi.org/10.1200/JCO-24-02782')],style='clinical_scenario')

q('Which vaccination principle is appropriate for a patient about to receive substantial immunosuppressive cancer treatment?', 'Review immunization status early, use indicated nonlive vaccines with appropriate timing, and avoid live vaccines during significant immunosuppression',[
 ('All vaccines are live and therefore permanently forbidden','Nonlive vaccines have an important preventive role.'),('Live and nonlive vaccines have identical safety during profound immunosuppression','Live vaccines can pose a distinct infection risk.'),('Vaccination status never matters after cancer diagnosis','Cancer and treatment can increase vaccine-preventable infection risk.')],
 'Vaccine type and immune state determine timing','**Nonlive vaccines do not carry the same replication risk as live vaccines.**',['Immune responses may be attenuated during treatment.','Anti-B-cell therapy and transplantation can require special timing or revaccination pathways.'],'**Follow current oncology and immunization guidance.**',['Review household and exposure precautions where relevant.','Do not delay urgent cancer treatment solely to complete an elective vaccine series without specialist review.'],[['Nonlive','Generally safe; response may vary'],['Live','Avoid during significant immunosuppression'],['Timing','Plan before treatment when possible']],[ref('ASCO vaccination of adults with cancer guideline','https://doi.org/10.1200/JCO.24.00032')])

q('A patient is HBsAg-negative and anti-HBc-positive before rituximab-containing treatment. Which principle is most appropriate?', 'Recognize substantial HBV-reactivation risk and arrange an antiviral prophylaxis strategy with appropriate monitoring',[
 ('Negative HBsAg makes reactivation impossible','Past infection can reactivate during anti-CD20 therapy.'),('Use vaccination alone as treatment for latent infection','Vaccination does not eliminate established latent HBV.'),('Wait for jaundice before assessing viral replication','Reactivation can precede clinical hepatitis and become severe.')],
 'Resolved serology does not mean no latent viral reservoir','**Anti-CD20 therapy is a high-risk context for HBV reactivation.**',['Baseline HBsAg, anti-HBc and anti-HBs help characterize status.','Choice and duration of prophylaxis follow current guidance and treatment exposure.'],'**Coordinate antiviral planning before therapy without unnecessary cancer-treatment delay.**',['Use an appropriate potent antiviral through the risk period.','Continue surveillance after treatment according to the specialist plan.'],[['Serology','Past infection possible'],['Exposure','Anti-CD20 high risk'],['Prevention','Antiviral prophylaxis and monitoring']],[ref('ASCO HBV screening and management opinion','https://doi.org/10.1200/JCO.20.01757')],style='clinical_scenario')

q('A patient with advanced cancer continues to lose muscle despite family efforts to increase food intake. Which explanation best describes cancer cachexia?', 'A multifactorial syndrome involving metabolic and inflammatory changes that is not fully reversed by conventional nutritional support alone',[
 ('It is always voluntary food refusal','That ignores biological, symptomatic and psychological contributors.'),('A feeding tube necessarily reverses the underlying syndrome in every patient','Artificial nutrition is not a universal reversal strategy.'),('Nutritional assessment is pointless because inflammation is involved','Treatable intake barriers and nutritional needs still warrant care.')],
 'Weight loss may reflect more than a calorie deficit','**Cachexia includes muscle loss and altered metabolism.**',['Pain, nausea, obstruction, depression and other reversible factors can worsen intake.','Dietary counseling and symptom control remain valuable.'],'**Use individualized multimodal supportive care.**',['Discuss realistic benefits and burdens of artificial nutrition.','Consider evidence-based appetite treatment selectively rather than promising restoration of muscle.'],[['Starvation alone','Primarily intake deficit'],['Cachexia','Metabolic/inflammatory component'],['Care','Symptoms, counseling and individualized support']],[ref('ASCO cancer cachexia guideline','https://doi.org/10.1200/JCO.20.00611')],style='clinical_scenario')

q('A patient with inoperable malignant bowel obstruction has persistent vomiting and a comfort-focused plan. Which medical strategy may reduce gastrointestinal secretions and symptoms?', 'An antisecretory regimen such as octreotide, with appropriate antiemetic and other individualized supportive treatment',[
 ('Force large oral meals to overcome complete obstruction','This can worsen distension and vomiting.'),('Use a prokinetic indiscriminately despite complete mechanical obstruction','Prokinetics require caution and are generally avoided in complete obstruction.'),('Assume symptom relief is impossible without curative surgery','Medical and selected decompressive approaches can provide palliation.')],
 'Symptom control is possible when anatomical cure is unavailable','**Malignant obstruction management depends on completeness, site, prognosis and goals.**',['Octreotide can reduce secretions and vomiting.','Selected corticosteroid, decompression, stent or surgical approaches may be appropriate in different cases.'],'**Create a route-appropriate symptom plan.**',['Reassess pain, fluid balance and patient priorities.','Avoid an intervention whose burden exceeds its expected benefit.'],[['Secretions','Antisecretory therapy'],['Vomiting','Antiemetic/decompression options'],['Complete obstruction','Avoid indiscriminate prokinetics']],[ref('MASCC malignant bowel obstruction recommendations','https://pmc.ncbi.nlm.nih.gov/articles/PMC9046338/')],style='clinical_scenario')

q('A patient with advanced cancer remains breathless despite treatment of reversible causes and nonpharmacological measures. Oxygen saturation is normal. Which approach is reasonable?', 'Consider carefully titrated systemic opioid therapy for refractory dyspnea; routine oxygen is not indicated solely because breathlessness is present',[
 ('Give progressively higher oxygen concentrations regardless of saturation and benefit','Oxygen is principally indicated for hypoxemia rather than every dyspnea sensation.'),('Avoid all opioids because they can never relieve dyspnea','Guidelines support selected use with careful titration and monitoring.'),('Treat the symptom as imaginary when saturation is normal','Breathlessness can be severe despite normal oxygen saturation.')],
 'Dyspnea is a symptom, not a synonym for hypoxemia','**Refractory breathlessness needs symptom-directed care after cause assessment.**',['A fan, positioning and pacing can help.','Opioid selection and dose must account for exposure, renal function and sedation risk.'],'**Set a monitored symptom-relief plan with the patient.**',['Use oxygen when hypoxemic or when a specific individualized trial demonstrates benefit.','Reassess new or abruptly worsening breathlessness for reversible emergencies.'],[['Normal saturation','Does not negate dyspnea'],['Nonpharmacological','Fan/positioning/pacing'],['Refractory symptom','Selected systemic opioid']],[ref('ASCO dyspnea in advanced cancer guideline','https://doi.org/10.1200/JCO.20.03465')],style='clinical_scenario')

q('A patient with decision-making capacity declines another chemotherapy line after discussing a small expected benefit and substantial toxicity. Which response is most appropriate?', 'Respect the informed decision and continue active symptom, psychosocial and supportive care',[
 ('Ask the family to override the capable patient solely because they prefer treatment','A capable patient’s informed choice guides care.'),('Stop all medical care because anticancer treatment was declined','Supportive care remains active and important.'),('Treat refusal alone as proof of incapacity','Disagreement with a recommendation does not itself establish incapacity.')],
 'An informed preference can change the treatment goal','**Capacity is decision-specific and requires an appropriate assessment.**',['Explain options, expected outcomes and uncertainty in understandable terms.','Explore reversible barriers without coercion.'],'**Document goals and maintain a reliable care plan.**',['Offer family involvement according to the patient’s wishes.','Revisit preferences if the patient requests or circumstances change.'],[['Capacity','Decision-specific assessment'],['Choice','Informed and voluntary'],['Ongoing care','Symptoms and support']],[PC],style='clinical_scenario')

q('In the final days of life, how should clinically assisted hydration be approached?', 'Individualize a goal-defined trial or decision based on symptoms, likely benefit, burden and the patient’s preferences',[
 ('It always prolongs life and relieves every symptom','Benefits are uncertain and context-dependent.'),('It is always harmful and must never be considered','Some patients may have a reasonable symptom-focused indication.'),('Dry mouth can only be treated by intravenous fluid','Mouth care and small tolerated sips can be more directly helpful.')],
 'A fluid prescription should have a defined clinical purpose','**Hydration can produce benefit or burden depending on the patient.**',['Fluid overload and secretions may worsen.','Thirst and dry mouth require direct symptom assessment and mouth care.'],'**Discuss uncertainty and reassess any trial.**',['Continue if the intended benefit is achieved without disproportionate harm.','Respect documented preferences and the current clinical situation.'],[['Potential benefit','Selected symptom relief'],['Potential burden','Overload/secretions'],['Decision','Individualized and reassessed']],[ref('NICE care of dying adults: hydration','https://www.nice.org.uk/guidance/ng31/chapter/Recommendations')])

q('A cancer survivor reports persistent fatigue. Which initial approach is most appropriate?', 'Assess reversible contributors and function, then offer evidence-based activity and behavioral strategies suited to the patient',[
 ('Prescribe indefinite bed rest as the universal treatment','Inactivity can worsen deconditioning.'),('Assume fatigue always means recurrent cancer without evaluation','Recurrence is one possibility among many.'),('Escalate psychostimulants routinely before assessing anemia, sleep, mood or medicines','A structured assessment should guide treatment.')],
 'Fatigue is common but still requires a cause-oriented assessment','**Anemia, sleep disturbance, depression, endocrine disease and medicines can contribute.**',['Evaluate red flags and the cancer context.','Exercise and selected behavioral approaches can help when adapted to ability.'],'**Set achievable goals and monitor function.**',['Avoid blaming the patient for symptoms.','Use specialist rehabilitation or psychosocial support when needed.'],[['Assessment','Reversible contributors'],['Intervention','Adapted activity/behavioral care'],['Outcome','Function and symptom burden']],[ref('ASCO–SIO cancer-related fatigue guideline 2024','https://doi.org/10.1200/JCO.24.00541')],style='clinical_scenario')

q('A patient with advanced cancer reports hopelessness and thoughts of self-harm. Which response is most appropriate?', 'Arrange immediate safety and mental-health assessment while addressing pain, symptoms and psychosocial distress',[
 ('Assume these thoughts are inevitable and require no assessment','Potential self-harm requires an active safety response.'),('Treat with analgesic escalation alone without exploring intent or risk','Symptom control is important but does not replace mental-health assessment.'),('Dismiss the concern because palliative care is already involved','Team involvement does not eliminate the need for urgent reassessment.')],
 'Distress requires both symptom care and a safety assessment','**Depression, demoralization, delirium and uncontrolled symptoms may overlap.**',['Assess immediate intent, means and protective factors through an appropriate clinical pathway.','Include urgent specialist support and a safe care setting when indicated.'],'**Provide compassionate, coordinated care.**',['Address reversible suffering and social needs.','Involve trusted supports according to consent and clinical safety requirements.'],[['Immediate need','Safety assessment'],['Contributors','Symptoms, mood, cognition and social stress'],['Care','Coordinated oncology/palliative/mental health']],[PC],style='clinical_scenario')

if __name__=='__main__':finalize('Oncology',7,'Supportive and Palliative Care','onco-supportive',rows,24)
